changeSet.sql:
CREATE TABLE hd_collections (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    slug varchar(50) NOT NULL UNIQUE,
    name_ar text NOT NULL,
    name_en text NULL,
    name_ru text NULL,
    compiler_narrator_id uuid NULL REFERENCES hd_narrators(id),
    total_hadith integer NULL,
    metadata jsonb NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_hd_collections_compiler ON hd_collections(compiler_narrator_id);

-- hd_hadiths: primary_book_id (→lib_books) → collection_id (→hd_collections)
ALTER TABLE hd_hadiths DROP CONSTRAINT fk_hd_hadiths_book;
ALTER TABLE hd_hadiths DROP CONSTRAINT hd_hadiths_book_number_unique;
DROP INDEX idx_hd_hadiths_book;
ALTER TABLE hd_hadiths RENAME COLUMN primary_book_id TO collection_id;
ALTER TABLE hd_hadiths ADD CONSTRAINT fk_hd_hadiths_collection
    FOREIGN KEY (collection_id) REFERENCES hd_collections(id);
ALTER TABLE hd_hadiths ADD CONSTRAINT hd_hadiths_collection_number_unique
    UNIQUE (collection_id, primary_number);
CREATE INDEX idx_hd_hadiths_collection ON hd_hadiths(collection_id);

-- hd_matns: source_book_id (→lib_books) → collection_id (→hd_collections)
ALTER TABLE hd_matns DROP CONSTRAINT fk_hd_matns_book;
DROP INDEX idx_hd_matns_book;
ALTER TABLE hd_matns RENAME COLUMN source_book_id TO collection_id;
ALTER TABLE hd_matns ADD CONSTRAINT fk_hd_matns_collection
    FOREIGN KEY (collection_id) REFERENCES hd_collections(id);
CREATE INDEX idx_hd_matns_collection ON hd_matns(collection_id);

changeSet.rollback:
DROP INDEX idx_hd_matns_collection;
ALTER TABLE hd_matns DROP CONSTRAINT fk_hd_matns_collection;
ALTER TABLE hd_matns RENAME COLUMN collection_id TO source_book_id;
CREATE INDEX idx_hd_matns_book ON hd_matns(source_book_id);
ALTER TABLE hd_matns ADD CONSTRAINT fk_hd_matns_book
    FOREIGN KEY (source_book_id) REFERENCES lib_books(id);

DROP INDEX idx_hd_hadiths_collection;
ALTER TABLE hd_hadiths DROP CONSTRAINT hd_hadiths_collection_number_unique;
ALTER TABLE hd_hadiths DROP CONSTRAINT fk_hd_hadiths_collection;
ALTER TABLE hd_hadiths RENAME COLUMN collection_id TO primary_book_id;
CREATE INDEX idx_hd_hadiths_book ON hd_hadiths(primary_book_id);
ALTER TABLE hd_hadiths ADD CONSTRAINT hd_hadiths_book_number_unique
    UNIQUE (primary_book_id, primary_number);
ALTER TABLE hd_hadiths ADD CONSTRAINT fk_hd_hadiths_book
    FOREIGN KEY (primary_book_id) REFERENCES lib_books(id);

DROP INDEX idx_hd_collections_compiler;
DROP TABLE hd_collections;
